parameters.jsCode:
const rawText = $json.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error('Gemini returned empty response');
}

// Remove markdown code fences if Gemini adds them
const cleanedText = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let result;

try {
  result = JSON.parse(cleanedText);
} catch (error) {
  throw new Error('Invalid JSON returned by Gemini');
}

// Required fields
const requiredFields = [
  'intent',
  'lead_score',
  'language',
  'summary',
  'suggested_reply',
  'needs_human'
];

for (const field of requiredFields) {
  if (!(field in result)) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// Validate intent
const allowedIntents = [
  'price',
  'schedule',
  'job_placement',
  'complaint',
  'spam',
  'other'
];

if (!allowedIntents.includes(result.intent)) {
  throw new Error(`Invalid intent: ${result.intent}`);
}

// Validate lead score
if (
  typeof result.lead_score !== 'number' ||
  result.lead_score < 1 ||
  result.lead_score > 10
) {
  throw new Error('lead_score must be a number between 1 and 10');
}

// Validate language
const allowedLanguages = ['bn', 'en', 'mixed'];

if (!allowedLanguages.includes(result.language)) {
  throw new Error(`Invalid language: ${result.language}`);
}

// Validate needs_human
if (typeof result.needs_human !== 'boolean') {
  throw new Error('needs_human must be true or false');
}

// Return clean structured data
return {
  json: {
    name: $('Prepare Gemini Input').item.json.name,
    email: $('Prepare Gemini Input').item.json.email,
    phone_masked: $('Prepare Gemini Input').item.json.phone,
    course_interest: $('Prepare Gemini Input').item.json.course_interest,
    message: $('Prepare Gemini Input').item.json.message,

    intent: result.intent,
    lead_score: result.lead_score,
    language: result.language,
    summary: result.summary,
    suggested_reply: result.suggested_reply,
    needs_human: result.needs_human
  }
};

